import uuid
from datetime import date

from pydantic import BaseModel, ConfigDict, Field, model_validator


class Experience(BaseModel):
    """Experience data sent by the client; the id is generated by the server."""

    title: str = Field(min_length=1)
    company: str = Field(min_length=1)
    location: str | None = None
    start_date: date
    end_date: date | None = Field(default=None, description="Empty means current position")
    description: str | None = None

    # Runs after field validation, so both dates are already `date` objects.
    @model_validator(mode="after")
    def check_end_date_not_before_start_date(self) -> "Experience":
        """Reject an end date that is before the start date."""
        if self.end_date is not None and self.end_date < self.start_date:
            raise ValueError("end_date cannot be before start_date")
        return self


class ExperienceRead(Experience):
    """Experience returned by the API, including its id."""

    # Allows building from ORM objects: ExperienceRead.model_validate(experience_orm).
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
